import { palette } from '../theme/palette';

// Web app manifest. Android builds its launch splash from the name, the
// background colour and these icons (generated by `npm run brand`).
export default function manifest() {
  return {
    name: 'Quit Quest',
    short_name: 'Quit Quest',
    description: 'Turn your quit smoking journey into an epic RPG adventure!',
    start_url: '/',
    display: 'standalone',
    orientation: 'portrait',
    background_color: palette.indigo950,
    theme_color: palette.indigo900,
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: '/icons/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
